export type Img = {w: number, h: number, data: Uint8ClampedArray};
export type Mask = {w: number, h: number, m: Uint8Array};
export function paperColor(img: Img): [number, number, number];
export function paperCoverage(img: Img, paper: number[], tol?: number): number;
export function contrastMask(img: Img, paper: number[], minDist: number): Mask;
export function openLine(mask: Mask, len: number, dir: "h" | "v"): Mask;
export function closeLine(mask: Mask, len: number, dir: "h" | "v"): Mask;
export function openSquare(mask: Mask, k: number): Mask;
export function closeSquare(mask: Mask, k: number): Mask;
export function maskOr(...ms: Mask[]): Mask;
export function maskNot(m: Mask): Mask;
export function components(mask: Mask, value?: number): {labels: Int32Array, count: number, stats: {area: number, x0: number, y0: number, x1: number, y1: number}[]};
export function floodFromEdges(free: Mask): Mask;
export function dominantAngle(mask: Mask, range?: number, step?: number): number;
export function angleContrast(mask: Mask, range?: number, step?: number): {angle: number, best: number, worst: number};
export function rotateImg(img: Img, deg: number, fill?: number[], expand?: boolean): Img;
export function rotatePoint(p: [number, number], deg: number, from: {w: number, h: number}, to: {w: number, h: number}): [number, number];
export function dilate(mask: Mask, r: number): Mask;
export function distance(mask: Mask): Float32Array;
